(function(){
'use strict';
const CFG={ballR:11,friction:.986,stop:4,maxPower:1500,cushion:.91,ballBounce:.97,pocketR:23,colors:['#f2c230','#1769aa','#d62f36','#6f3fa0','#e66b25','#24834b','#7d1f25','#111111','#f2c230','#1769aa','#d62f36','#6f3fa0','#e66b25','#24834b','#7d1f25']};
const TABLES=[['Verde clássico','#16734a'],['Azul profissional','#176a9a'],['Vinho','#7a2638'],['Preto','#20242a'],['Roxo','#56357d'],['GameLab Neon','#087b75']];
class AudioFX{constructor(){this.enabled=true;this.ctx=null}tone(f=180,d=.035,v=.035){if(!this.enabled)return;try{this.ctx=this.ctx||new(window.AudioContext||window.webkitAudioContext)();const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.frequency.value=f;g.gain.value=v;o.connect(g);g.connect(this.ctx.destination);o.start();g.gain.exponentialRampToValueAtTime(.001,this.ctx.currentTime+d);o.stop(this.ctx.currentTime+d)}catch(e){}}hit(s=.5){this.tone(130+s*120,.025,.02+s*.025)}pocket(){this.tone(90,.12,.07)}cue(){this.tone(220,.045,.05)}}
const $=id=>document.getElementById(id), canvas=$('game'), ctx=canvas.getContext('2d'), wrap=$('tableWrap'), audio=new AudioFX();
let balls=[],aim={x:0,y:0},charge=0,last=0,shots=0,potted=0,started=false,pendingCloth=localStorage.getItem('pool-cloth')||TABLES[0][1],cloth=pendingCloth; const rail=34;
const W=()=>wrap.clientWidth,H=()=>wrap.clientHeight;
function round(x,y,w,h,r){ctx.beginPath(); if(ctx.roundRect)ctx.roundRect(x,y,w,h,r); else ctx.rect(x,y,w,h)}
function pockets(){let w=W(),h=H();return[[rail,rail],[w/2,rail-2],[w-rail,rail],[rail,h-rail],[w/2,h-rail+2],[w-rail,h-rail]]}
function ball(n,x,y){return{n,x,y,vx:0,vy:0,r:CFG.ballR,pocketed:false}}
function rack(){balls=[];let w=W(),h=H(),r=CFG.ballR,gap=r*2+.8;balls.push(ball(0,w*.27,h/2));let nums=[1,9,2,10,8,3,11,4,12,5,13,6,14,7,15],k=0,x0=w*.68;for(let row=0;row<5;row++)for(let j=0;j<=row;j++){balls.push(ball(nums[k++],x0+row*gap*.87,h/2-row*gap/2+j*gap))}shots=0;potted=0;charge=0;aim={x:w*.55,y:h/2};hud()}
function resize(){let d=Math.min(window.devicePixelRatio||1,2),r=wrap.getBoundingClientRect();canvas.width=Math.max(1,r.width*d);canvas.height=Math.max(1,r.height*d);ctx.setTransform(d,0,0,d,0,0);if(started&&balls.length===0)rack()}
function moving(){return balls.some(b=>!b.pocketed&&Math.hypot(b.vx,b.vy)>CFG.stop)}
function collide(a,b){if(a.pocketed||b.pocketed)return;let dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy),min=a.r+b.r;if(!d||d>=min)return;let nx=dx/d,ny=dy/d,over=min-d;a.x-=nx*over/2;a.y-=ny*over/2;b.x+=nx*over/2;b.y+=ny*over/2;let rv=(b.vx-a.vx)*nx+(b.vy-a.vy)*ny;if(rv>=0)return;let imp=-rv*CFG.ballBounce;a.vx-=imp*nx;a.vy-=imp*ny;b.vx+=imp*nx;b.vy+=imp*ny;audio.hit(Math.min(1,Math.abs(rv)/500))}
function respawnCue(){let q=balls.find(b=>b.n===0);if(!q)return;q.pocketed=false;q.x=W()*.27;q.y=H()/2;q.vx=q.vy=0;hud()}
function update(dt){if(!started)return;for(let b of balls){if(b.pocketed)continue;b.x+=b.vx*dt;b.y+=b.vy*dt;b.vx*=Math.pow(CFG.friction,dt*60);b.vy*=Math.pow(CFG.friction,dt*60);if(Math.hypot(b.vx,b.vy)<CFG.stop)b.vx=b.vy=0;if(pockets().some(p=>Math.hypot(b.x-p[0],b.y-p[1])<CFG.pocketR)){b.pocketed=true;b.vx=b.vy=0;if(b.n===0)setTimeout(respawnCue,650);else potted++;audio.pocket();hud();continue}if(b.x-b.r<rail){b.x=rail+b.r;b.vx=Math.abs(b.vx)*CFG.cushion}if(b.x+b.r>W()-rail){b.x=W()-rail-b.r;b.vx=-Math.abs(b.vx)*CFG.cushion}if(b.y-b.r<rail){b.y=rail+b.r;b.vy=Math.abs(b.vy)*CFG.cushion}if(b.y+b.r>H()-rail){b.y=H()-rail-b.r;b.vy=-Math.abs(b.vy)*CFG.cushion}}for(let i=0;i<balls.length;i++)for(let j=i+1;j<balls.length;j++)collide(balls[i],balls[j]);hud()}
function drawBall(b){let striped=b.n>8,g=ctx.createRadialGradient(b.x-4,b.y-5,2,b.x,b.y,b.r);if(b.n===0){g.addColorStop(0,'#fff');g.addColorStop(1,'#d9dde1')}else{g.addColorStop(0,'#fff');g.addColorStop(.28,striped?'#f8f8f2':CFG.colors[b.n-1]);g.addColorStop(1,CFG.colors[b.n-1])}ctx.beginPath();ctx.fillStyle=g;ctx.arc(b.x,b.y,b.r,0,Math.PI*2);ctx.fill();if(b.n){ctx.beginPath();ctx.fillStyle='#f7f5e9';ctx.arc(b.x,b.y,5.4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#111';ctx.font='bold 6.5px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(b.n,b.x,b.y)}}
function draw(){let w=W(),h=H();ctx.clearRect(0,0,w,h);ctx.fillStyle='#5a321d';round(4,4,w-8,h-8,28);ctx.fill();ctx.fillStyle='#2b170e';round(16,16,w-32,h-32,22);ctx.fill();ctx.fillStyle=cloth;round(rail,rail,w-rail*2,h-rail*2,12);ctx.fill();for(let p of pockets()){ctx.beginPath();ctx.fillStyle='#07090b';ctx.arc(p[0],p[1],CFG.pocketR,0,Math.PI*2);ctx.fill()}if(!started)return;let q=balls.find(b=>b.n===0);if(q&&!q.pocketed&&!moving()){let dx=aim.x-q.x,dy=aim.y-q.y,l=Math.hypot(dx,dy)||1,nx=dx/l,ny=dy/l;ctx.setLineDash([7,7]);ctx.strokeStyle='rgba(255,255,255,.65)';ctx.beginPath();ctx.moveTo(q.x,q.y);ctx.lineTo(q.x+nx*260,q.y+ny*260);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle='rgba(214,176,112,.95)';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(q.x-nx*(45+charge*.08),q.y-ny*(45+charge*.08));ctx.lineTo(q.x-nx*(185+charge*.08),q.y-ny*(185+charge*.08));ctx.stroke()}for(let b of balls)if(!b.pocketed)drawBall(b)}
function hud(){$('shots').textContent=shots;$('potted').textContent=potted;$('cueState').textContent=started?'PRONTA':'AGUARDE';$('status').textContent=!started?'CLIQUE EM INICIAR':moving()?'BOLAS EM MOVIMENTO':charge>0?'FORÇA DEFINIDA':'MIRE';$('powerText').textContent=Math.round(charge/CFG.maxPower*100)+'%';$('powerFill').style.width=(charge/CFG.maxPower*100)+'%'}
function frame(t){let dt=Math.min((t-last)/1000,.025)||0;last=t;update(dt);draw();requestAnimationFrame(frame)}
function pos(e){let r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}
function shoot(){if(!started||moving()||charge<=0)return;let q=balls.find(b=>b.n===0);if(!q||q.pocketed)return;let dx=aim.x-q.x,dy=aim.y-q.y,l=Math.hypot(dx,dy)||1;q.vx=dx/l*charge;q.vy=dy/l*charge;shots++;audio.cue();charge=0;hud()}
function message(title,text){$('message').innerHTML='<b>'+title+'</b><span>'+text+'</span>';$('message').classList.remove('hide')}
function startGame(){started=true;rack();message('JOGO INICIADO','Mire com o mouse, ajuste a força com a rodinha e pressione ESPAÇO.');setTimeout(()=>$('message').classList.add('hide'),1800);$('startGame').innerHTML='<i class="fa fa-play"></i> Reiniciar jogo'}
function setPending(name,c){pendingCloth=c;$('tableName').textContent=name;$('customColor').value=c}
function applyCloth(){cloth=pendingCloth;localStorage.setItem('pool-cloth',cloth);message('MESA ATUALIZADA','A nova cor foi aplicada.');setTimeout(()=>$('message').classList.add('hide'),1000)}
TABLES.forEach(([n,c])=>{let b=document.createElement('button');b.className='swatch';b.style.background=c;b.title=n;b.addEventListener('click',()=>setPending(n,c));$('swatches').appendChild(b)});
$('customColor').addEventListener('input',e=>setPending('Personalizada',e.target.value));$('applyTable').addEventListener('click',applyCloth);$('startGame').addEventListener('click',startGame);$('newGame').addEventListener('click',startGame);$('resetCue').addEventListener('click',()=>{if(started&&!moving())respawnCue()});
canvas.addEventListener('pointermove',e=>{if(!started)return;aim=pos(e);$('message').classList.add('hide')});canvas.addEventListener('wheel',e=>{e.preventDefault();if(!started||moving())return;charge=Math.max(0,Math.min(CFG.maxPower,charge+(e.deltaY>0?100:-100)));hud()},{passive:false});
window.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();shoot()}else if(started&&e.code==='ArrowUp'&&!moving()){charge=Math.min(CFG.maxPower,charge+75);hud()}else if(started&&e.code==='ArrowDown'&&!moving()){charge=Math.max(0,charge-75);hud()}});
$('theme').addEventListener('click',()=>{let h=document.documentElement;h.dataset.theme=h.dataset.theme==='dark'?'light':'dark';localStorage.setItem('pool-theme',h.dataset.theme)});$('sound').addEventListener('click',()=>{audio.enabled=!audio.enabled;$('sound').innerHTML='<i class="fa fa-volume-'+(audio.enabled?'up':'off')+'"></i>'});
document.documentElement.dataset.theme=localStorage.getItem('pool-theme')||'dark';setPending('Salva',pendingCloth);window.addEventListener('resize',resize);resize();hud();message('🎱 Pool Ultimate','Escolha a cor da mesa, clique em Aplicar e depois em Iniciar jogo.');requestAnimationFrame(frame);
})();
